select tcdId, tcId, projectId, activityId, workingDate, startTime , endTime , workingHours,  status from 
	timecarddetails where tcId = #{tcId} and workingDate=#{workingDate} 
	and startTime>=#{startTime} and endTime<=#{endTime}

SELECT ifnull(tcdid,'-1')
FROM TimeCardDetails WHERE tcdId= #{tcdId} and
tcId= #{tcId}
